mapper.select:
SELECT 
  FROM HR_RECRUIT_REGISTER_INFO A
 WHERE A.CPNY_ID = #{cpnyId, jdbcType=VARCHAR}
   AND A.ACTIVITY <> 2

   AND A.REGISTER_TYPE = #{searchRegisterType, jdbcType=VARCHAR}


   AND A.ACTIVITY = #{searchActivity, jdbcType=VARCHAR}


   AND TO_DATE(A.REGISTER_INFO, 'DD/MM/YYYY') >= TO_DATE(#{searchStartDate, jdbcType=VARCHAR}, 'DD/MM/YYYY')


   AND TO_DATE(A.REGISTER_INFO, 'DD/MM/YYYY') <= TO_DATE(#{searchEndDate, jdbcType=VARCHAR}, 'DD/MM/YYYY')

 ORDER BY A.CREATE_DATE DESC

SELECT 
  FROM HR_RECRUIT_REGISTER_INFO A
 WHERE A.SEQ = #{seq, jdbcType=VARCHAR}
   AND A.CPNY_ID = #{cpnyId, jdbcType=VARCHAR}
   AND A.ACTIVITY <> 2

mapper.update:
UPDATE HR_RECRUIT_REGISTER_INFO
   SET REGISTER_TYPE = #{registerType, jdbcType=VARCHAR},
       REGISTER_DATE = #{registerDate, jdbcType=VARCHAR},
       REMARK        = #{remark, jdbcType=VARCHAR},
       UPDATE_DATE   = SYSDATE,
       UPDATED_BY    = #{adminID, jdbcType=VARCHAR},
       UPDATED_IP    = #{adminIP, jdbcType=VARCHAR}
 WHERE SEQ = #{seq, jdbcType=VARCHAR}
   AND CPNY_ID = #{cpnyId, jdbcType=VARCHAR}
   AND ACTIVITY = 0

UPDATE HR_RECRUIT_REGISTER_INFO
   SET ACTIVITY    = 2,
       UPDATE_DATE = SYSDATE,
       UPDATED_BY  = #{adminID, jdbcType=VARCHAR},
       UPDATED_IP  = #{adminIP, jdbcType=VARCHAR}
 WHERE SEQ = #{seq, jdbcType=VARCHAR}
   AND CPNY_ID = #{cpnyId, jdbcType=VARCHAR}
   AND ACTIVITY = 0

mapper.select:
SELECT A.PERSON_ID, B.EMPID, B.LOCAL_NAME, A.START_DATE ORDER_DATE, GET_GLOBAL_NAME(A.TRANS_CODE, #{lang, jdbcType=VARCHAR}) TRANS_CODE_NAME, GET_GLOBAL_NAME(A.TRANS_RESOURCE, #{lang, jdbcType=VARCHAR}) TRANS_RESOURCE_NAME, GET_DEPT_NAME(A.DEPTNO, #{lang, jdbcType=VARCHAR}) DEPT_NAME, GET_GLOBAL_NAME(A.EMP_TYPE_CODE, #{lang, jdbcType=VARCHAR}) EMP_TYPE_NAME, GET_GLOBAL_NAME(A.POST_GRADE_NO, #{lang, jdbcType=VARCHAR}) POST_GRADE_NAME, GET_GLOBAL_NAME(A.POST_FAMILY, #{lang, jdbcType=VARCHAR}) POST_FAMILY_NAME, GET_GLOBAL_NAME(A.MAIN_BUSINESS, #{lang, jdbcType=VARCHAR}) MAIN_BUSINESS_NAME, GET_GLOBAL_NAME(A.POSITION_NO, #{lang, jdbcType=VARCHAR}) POSITION_NAME, GET_GLOBAL_NAME(A.EMP_OFFICE, #{lang, jdbcType=VARCHAR}) EMP_OFFICE_NAME, TO_CHAR(B.DATE_STARTED, 'DD/MM/YYYY') DATE_STARTED, A.REMARK FROM HR_EXPERIENCE_INSIDE A, HR_EMPLOYEE B, HR_PERSONAL_INFO C WHERE A.PERSON_ID = B.PERSON_ID AND A.PERSON_ID = C.PERSON_ID AND A.ACTIVITY <> 0 AND B.CPNY_ID = #{cpnyId, jdbcType=VARCHAR} AND B.EMPID NOT LIKE '111111%'
AND (B.EMPID LIKE '%' || #{keyword, jdbcType=VARCHAR} || '%' OR CONVERTTOUNSIGN(UPPER(B.LOCAL_NAME)) LIKE '%' || CONVERTTOUNSIGN(UPPER(#{keyword, jdbcType=VARCHAR})) || '%')
AND TO_DATE(A.START_DATE, 'DD/MM/YYYY') >= TO_DATE(#{startDate, jdbcType=VARCHAR}, 'DD/MM/YYYY')
AND TO_DATE(A.START_DATE, 'DD/MM/YYYY') <= TO_DATE(#{endDate, jdbcType=VARCHAR}, 'DD/MM/YYYY')
AND B.DATE_STARTED >= TO_DATE(#{startDateJoin, jdbcType=VARCHAR}, 'DD/MM/YYYY')
AND B.DATE_STARTED <= TO_DATE(#{endDateJoin, jdbcType=VARCHAR}, 'DD/MM/YYYY')
AND A.TRANS_CODE IN #{c, jdbcType=VARCHAR}
AND A.TRANS_RESOURCE IN #{c, jdbcType=VARCHAR}
AND B.POST_FAMILY IN #{c, jdbcType=VARCHAR}
AND B.EMP_TYPE_CODE IN #{c, jdbcType=VARCHAR}
AND A.EMP_OFFICE IN #{c, jdbcType=VARCHAR}
AND B.DEPTNO IN (SELECT DEPTNO FROM HR_DEPARTMENT WHERE CPNY_ID = #{cpnyId, jdbcType=VARCHAR} START WITH DEPTNO = #{deptNo, jdbcType=VARCHAR} CONNECT BY PRIOR DEPTNO = PARENT_DEPT_NO)
AND B.DEPTNO = #{deptNo, jdbcType=VARCHAR}
ORDER BY TO_DATE(A.START_DATE, 'DD/MM/YYYY') DESC, B.EMPID
